import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    static class Modular {
        int value;

        Modular(long v) {
            v %= MOD;
            if (v < 0) v += MOD;
            value = (int) v;
        }

        static int inverse(int a, int m) {
            int g = m, r = a, x = 0, y = 1;
            while (r != 0) {
                int q = g / r;
                int tmp = g % r;
                g = r;
                r = tmp;
                int x1 = x - q * y;
                x = y;
                y = x1;
            }
            return x < 0 ? x + m : x;
        }

        Modular add(Modular other) {
            int res = value + other.value;
            if (res >= MOD) res -= MOD;
            return new Modular(res);
        }

        Modular subtract(Modular other) {
            int res = value - other.value;
            if (res < 0) res += MOD;
            return new Modular(res);
        }

        Modular multiply(Modular other) {
            long res = (long) value * other.value % MOD;
            return new Modular(res);
        }

        Modular divide(Modular other) {
            return this.multiply(new Modular(inverse(other.value, MOD)));
        }

        Modular inv() {
            return new Modular(inverse(value, MOD));
        }

        Modular pow(long p) {
            Modular base = this;
            Modular result = new Modular(1);
            while (p > 0) {
                if ((p & 1) == 1) result = result.multiply(base);
                base = base.multiply(base);
                p >>= 1;
            }
            return result;
        }

        @Override
        public int hashCode() {
            return value;
        }

        @Override
        public boolean equals(Object obj) {
            if (!(obj instanceof Modular)) return false;
            return value == ((Modular) obj).value;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        Modular[][] prob = new Modular[N][N];
        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().split(" ");
            for (int j = 0; j < N; j++) {
                int p = Integer.parseInt(parts[j]);
                prob[i][j] = new Modular(p).divide(new Modular(100));
            }
        }

        List<List<Integer>> masksByCount = new ArrayList<>();
        for (int i = 0; i <= N; i++) {
            masksByCount.add(new ArrayList<>());
        }
        int[] lookup = new int[1 << N];
        Arrays.fill(lookup, -1);
        for (int mask = 0; mask < (1 << N); mask++) {
            int c = Integer.bitCount(mask);
            lookup[mask] = masksByCount.get(c).size();
            masksByCount.get(c).add(mask);
        }

        Map<Long, Modular> possible = new HashMap<>();
        long initialMask = 1L << lookup[0];
        possible.put(initialMask, new Modular(1));

        for (int left = 0; left < N; left++) {
            Map<Long, Modular> newPossible = new HashMap<>();
            for (int current_mask = 0; current_mask < (1 << N); current_mask++) {
                Modular product = new Modular(1);
                for (int right = 0; right < N; right++) {
                    boolean bitSet = ((current_mask >> right) & 1) == 1;
                    if (bitSet) {
                        product = product.multiply(prob[left][right]);
                    } else {
                        product = product.multiply(new Modular(1).subtract(prob[left][right]));
                    }
                }
                for (Map.Entry<Long, Modular> p : possible.entrySet()) {
                    long maskVal = p.getKey();
                    Modular probVal = p.getValue();
                    long new_mask_val = 0;
                    for (int m : masksByCount.get(left)) {
                        if (((maskVal >> lookup[m]) & 1) == 1) {
                            for (int i = 0; i < N; i++) {
                                if (((current_mask >> i) & 1) == 1 && ((m >> i) & 1) == 0) {
                                    long newMask = m | (1 << i);
                                    new_mask_val |= 1L << lookup[newMask];
                                }
                            }
                        }
                    }
                    newPossible.put(new_mask_val, newPossible.getOrDefault(new_mask_val, new Modular(0)).add(probVal.multiply(product)));
                }
            }
            possible = newPossible;
        }

        Modular answer = new Modular(0);
        int last_mask_index = lookup[(1 << N) - 1];
        for (Map.Entry<Long, Modular> p : possible.entrySet()) {
            if (((p.getKey() >> last_mask_index) & 1) == 1) {
                answer = answer.add(p.getValue());
            }
        }
        System.out.println(answer.value);
    }
}
